"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
from heapq import heappop, heappush
from collections import deque


@dataclass
class Edge:
    src: int
    dst: int
    weight: float


class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def _dijkstra(
    graph: WeightedGraph,
    source: int,
    target: Optional[int] = None
) -> Tuple[Dict[int, float], Dict[int, Optional[int]]]:
    """Run Dijkstra from source. If target is given, stops once target is settled."""
    nodes = graph.nodes
    if source not in nodes:
        return {}, {}

    inf = float("inf")
    dist: Dict[int, float] = {n: inf for n in nodes}
    prev: Dict[int, Optional[int]] = {n: None for n in nodes}
    dist[source] = 0.0

    heap: List[Tuple[float, int]] = [(0.0, source)]

    while heap:
        d, u = heappop(heap)
        if d > dist[u]:
            continue

        if target is not None and u == target:
            break

        for v, weight in graph.neighbors(u):
            if v not in dist:
                continue
            nd = d + weight
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heappush(heap, (nd, v))

    return dist, prev


def _reconstruct_path(
    prev: Dict[int, Optional[int]],
    source: int,
    target: int
) -> List[int]:
    """Reconstruct path from source to target using predecessor map."""
    path: List[int] = []
    cur: Optional[int] = target

    while cur is not None:
        path.append(cur)
        if cur == source:
            path.reverse()
            return path
        cur = prev[cur]

    return []


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Time: O((V+E) log V) using Dijkstra + binary heap.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist, prev = _dijkstra(graph, source, target)

    if target not in dist or dist[target] == float("inf"):
        return None, []

    path = _reconstruct_path(prev, source, target)
    if not path:
        return None, []

    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Time: O((V+E) log V) for the shortest-path computation.
    Path materialization is proportional to the size of the returned paths.
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist, prev = _dijkstra(graph, source)

    result: Dict[int, Tuple[float, List[int]]] = {}
    inf = float("inf")
    for node in nodes:
        if dist[node] != inf:
            result[node] = (dist[node], _reconstruct_path(prev, source, node))
    return result


